/// <summary>
///    The <c>UnitOfMeasureLookup</c> class provides the methods to perform lookup on the
///    <c>EcoResProduct</c> table, controls the <c>EcoResProductLookup</c> lookup form behavior, and
///    handles form events.
/// </summary>
class GUPCompanyNAFCodeLookup
{
    public  boolean returnRefRecId = false;

}

Method.Source:
    final public boolean parmreturnRefRecID(boolean _returnRefRecId = returnRefRecId)
    {
        returnRefRecId = _returnRefRecId;

        return returnRefRecId;
    }

    public CompanyNAFCode performLookup(FormStringControl _formStringControl)
    {
        Args args = new Args();
        args.name(formStr(GUPCompanyNAFCodeLookup));
        args.caller(this);

        args.parmObject(this);
        args.lookupField(fieldNum(CompanyNAFCode, RecId));
        args.lookupValue(_formStringControl.valueStr());

        FormRun formRun = classfactory.formRunClass(args);
        formRun.init();

        _formStringControl.performFormLookup(formRun);
        CompanyNAFCode companyNAFCode = formRun.selectRecordModeSelectedRecord() as CompanyNAFCode;

        return companyNAFCode;
    }

public static GUPCompanyNAFCodeLookup construct(boolean _returnRefRecID)
{
    return new GUPCompanyNAFCodeLookup(_returnRefRecID);
}
